<section class="card table-card"><div class="table-summary"><strong>Asset register</strong><span><?=e(count($data['assets']))?> records</span></div><div class="table-responsive"><table class="data-table"><thead><tr><th>Asset</th><th>Category</th><th>Assignment</th><th>Cost</th><th>Accumulated</th><th>NBV</th><th>Status</th></tr></thead><tbody><?php if($data['assets']===[]):?><tr><td colspan="7" class="empty-state">No fixed assets.</td></tr><?php endif;?><?php foreach($data['assets'] as $asset):?><tr><td><a href="/office_app/public/assets/<?=e($asset['asset_id'])?>"><strong><?=e($asset['asset_number'])?></strong><small><?=e($asset['asset_name'])?></small></a></td><td><?=e($asset['category_name'])?></td><td><?=e($asset['department_name']??'Unassigned')?><small><?=e($asset['custodian_name']??'No custodian')?></small></td><td><?=e($money((float)$asset['acquisition_cost']+(float)$asset['additional_capitalized_cost'],$asset['currency']))?></td><td><?=e($money($asset['accumulated_depreciation'],$asset['currency']))?></td><td><strong><?=e($money($asset['book_value'],$asset['currency']))?></strong></td><td><span class="badge badge-muted"><?=e(strtoupper(str_replace('_',' ',$asset['status'])))?></span></td></tr><?php endforeach;?></tbody></table></div></section>
<?php if($canManage):?><section class="card finance-filter-panel"><h2>New asset category</h2><form method="post" action="/office_app/public/assets/categories" class="finance-filter-form"><?=csrfField()?><div class="form-field"><label>Code</label><input name="category_code" required></div><div class="form-field"><label>Name</label><input name="category_name" required></div><div class="form-field"><label>Useful life (months)</label><input name="useful_life_months" type="number" min="1" value="36" required></div><div class="form-field"><label>Salvage behavior</label><select name="salvage_behavior"><option value="fixed">Fixed salvage</option><option value="zero">Zero salvage</option></select></div><?php foreach(['asset_account_id'=>'Asset account','accumulated_depreciation_account_id'=>'Accumulated depreciation','depreciation_expense_account_id'=>'Depreciation expense','disposal_gain_account_id'=>'Disposal gain','disposal_loss_account_id'=>'Disposal loss'] as $key=>$label):?><div class="form-field"><label><?=e($label)?></label><select name="<?=e($key)?>" required><option value="">Select account</option><?php foreach($data['accounts'] as $account):?><option value="<?=e($account['account_id'])?>"><?=e($account['account_code'].' · '.$account['account_name'].' ('.$account['normal_balance'].')')?></option><?php endforeach;?></select></div><?php endforeach;?><button class="btn btn-primary">Create category</button></form></section>
<section class="card finance-filter-panel"><h2>New direct asset</h2><form method="post" action="/office_app/public/assets" class="finance-filter-form"><?=csrfField()?><div class="form-field"><label>Asset number</label><input name="asset_number" required></div><div class="form-field"><label>Name</label><input name="asset_name" required></div><div class="form-field"><label>Category</label><select name="asset_category_id" required><?php foreach($data['categories'] as $category):?><option value="<?=e($category['asset_category_id'])?>"><?=e($category['category_code'].' · '.$category['category_name'])?></option><?php endforeach;?></select></div><div class="form-field"><label>Acquisition date</label><input type="date" name="acquisition_date" value="<?=e(date('Y-m-d'))?>" required></div><div class="form-field"><label>Cost</label><input type="number" name="acquisition_cost" min="0.01" step="0.01" required></div><div class="form-field"><label>Salvage value</label><input type="number" name="salvage_value" min="0" step="0.01" value="0"></div><div class="form-field"><label>Currency</label><input name="currency" value="<?=e($data['user']['company']['default_currency']??'ETB')?>" maxlength="3" required></div><div class="form-field"><label>Serial number</label><input name="serial_number"></div><div class="form-field"><label>Department</label><select name="department_id"><option value="">Unassigned</option><?php foreach($data['departments'] as $d):?><option value="<?=e($d['department_id'])?>"><?=e($d['name'])?></option><?php endforeach;?></select></div><div class="form-field"><label>Custodian</label><select name="custodian_employee_id"><option value="">Unassigned</option><?php foreach($data['employees'] as $e):?><option value="<?=e($e['employee_id'])?>"><?=e($e['name'])?></option><?php endforeach;?></select></div><div class="form-field"><label>Location</label><input name="location_name"></div><div class="form-field"><label>Vendor</label><input name="vendor_name"></div><button class="btn btn-primary">Create draft asset</button></form></section><?php endif;?>
<?php if($canCapitalize):?><section class="card finance-filter-panel"><h2>Capitalize inventory</h2><p>Issues available stock once, preserves source cost, and posts Inventory Asset → Fixed Asset reclassification.</p><form method="post" action="/office_app/public/assets/capitalize" class="finance-filter-form"><?=csrfField()?><div class="form-field"><label>Asset number</label><input name="asset_number" required></div><div class="form-field"><label>Asset name</label><input name="asset_name" required></div><div class="form-field"><label>Category</label><select name="asset_category_id" required><?php foreach($data['categories'] as $category):?><option value="<?=e($category['asset_category_id'])?>"><?=e($category['category_name'])?></option><?php endforeach;?></select></div><div class="form-field"><label>Source stock</label><select id="asset-stock" required><option value="">Select available stock</option><?php foreach($data['stock'] as $s):?><option value="<?=e($s['warehouse_id'].'|'.$s['location_id'].'|'.$s['product_id'])?>"><?=e($s['sku'].' · '.$s['product_name'].' · '.$s['warehouse_name'].'/'.$s['location_name'].' · available '.$s['available'])?></option><?php endforeach;?></select><input type="hidden" name="warehouse_id"><input type="hidden" name="location_id"><input type="hidden" name="product_id"></div><div class="form-field"><label>Quantity</label><input type="number" name="quantity" min="0.001" step="0.001" value="1" required></div><div class="form-field"><label>Acquisition date</label><input type="date" name="acquisition_date" value="<?=e(date('Y-m-d'))?>" required></div><div class="form-field"><label>Salvage value</label><input type="number" name="salvage_value" min="0" step="0.01" value="0"></div><div class="form-field"><label>Currency</label><input name="currency" value="<?=e($data['user']['company']['default_currency']??'ETB')?>" maxlength="3" required></div><div class="form-field"><label>Serial number</label><input name="serial_number"></div><button class="btn btn-primary">Capitalize selected stock</button></form></section><script>document.getElementById('asset-stock')?.addEventListener('change',e=>{const parts=e.target.value.split('|');['warehouse_id','location_id','product_id'].forEach((name,i)=>document.querySelector(`input[name="${name}"]`).value=parts[i]||'')});</script><?php endif;?></div>
